package android.app;import java.util.*;public class AlarmManager {public static final int RTC_WAKEUP=0;public final Map<String,PendingIntent> armed=new HashMap<>();public boolean canScheduleExactAlarms(){return true;}public void setExactAndAllowWhileIdle(int type,long at,PendingIntent p){armed.put(p.key,p);}public void setWindow(int t,long at,long w,PendingIntent p){armed.put(p.key,p);}public void cancel(PendingIntent p){armed.remove(p.key);}}
